import { ColumnDef } from "@tanstack/react-table";
import { Cause } from "@/types/causes";
import { DataTableColumnHeader } from "../table/tasks-table-column-header";
import Image from "next/image";
import { Badge } from "../ui/badge";

const columns: ColumnDef<Cause>[] = [
  {
    accessorKey: "id",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="ID" />
    ),
    cell: ({ row }) => (
      <div className="overflow-hidden">{row.getValue("id")}</div>
    ),
    enableSorting: false,
    enableHiding: false,
  },
  {
    accessorKey: "name",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Name" />
    ),
    cell: (info) => {
      const cause = info.row.original;
      return (
        <div className="flex min-w-64 items-center gap-4">
          <div className="relative h-16 w-16 shrink-0 overflow-hidden rounded-md">
            <Image
              src={"https://picsum.photos/200/200"}
              alt={cause.name}
              fill
              className="object-cover"
            />
          </div>
          <div className="flex flex-col">
            <span className="font-medium text-sm">{cause.name}</span>
            <span className="text-xs text-muted-foreground">
              {cause.category}
            </span>
          </div>
        </div>
      );
    },
  },
  {
    accessorKey: "organization",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Organization" />
    ),
    cell: (info) => info.getValue(),
  },
  {
    accessorKey: "finalAmount",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Final Amount" />
    ),
    cell: (info) => {
      const { amount, position } = info.row.original?.currentlyWinning;
      return (
        <div className="flex flex-col">
          <span className="font-medium">{amount}</span>
          <span className="text-xs text-muted-foreground">
            Position {position}
          </span>
        </div>
      );
    },
  },
  {
    accessorKey: "startedOn",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Started On" />
    ),
    cell: (info) => info.getValue(),
  },
  {
    accessorKey: "completedOn",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Completed On" />
    ),
    cell: (info) => info.getValue(),
  },
  {
    accessorKey: "totalBenefactors",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Total Benefactors" />
    ),
    cell: (info) => info.row.original?.benefactors.toLocaleString(),
  },
  {
    accessorKey: "totalPoints",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Total Points" />
    ),
    cell: (info) => {
      const { count, label } = info.row.original?.points;
      return (
        <div className="flex flex-col">
          <span className="font-medium">{count.toLocaleString()}</span>
          <span className="text-xs text-muted-foreground">{label}</span>
        </div>
      );
    },
  },
  {
    accessorKey: "type",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Type" />
    ),
    cell: (info) => {
      const type = info.row.original?.type;
      return (
        <Badge
          className="whitespace-nowrap"
          variant={type?.split(" ").join("-").toLowerCase() as any}
        >
          {type}
        </Badge>
      );
    },
  },
  {
    accessorKey: "status",
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="Status" />
    ),
    cell: (info) => {
      const status = info.row.original?.status;
      return (
        <Badge
          className="whitespace-nowrap"
          variant={status?.toLowerCase() as any}
        >
          {status}
        </Badge>
      );
    },
  },
];

export { columns as completedCauseColumns }; 